using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;
using OpenTelemetry;
using OpenTelemetry.Resources;
using OpenTelemetry.Trace;

namespace MyApp.Evals;

/// <summary>
/// Central configuration for evaluation modes: telemetry, quality, and compare.
/// </summary>
public static class EvalConfiguration
{
    private static readonly string StoragePath =
        Path.Combine(Path.GetTempPath(), "MyApp.Evals", "results");

    /// <summary>
    /// Creates a reporting configuration with disk-based result storage.
    /// </summary>
    public static ReportingConfiguration CreateReportingConfiguration(
        IEnumerable<IEvaluator> evaluators,
        string scenarioName,
        IChatClient chatClient)
    {
        var storage = new DiskBasedReportingStorage(StoragePath);

        return new ReportingConfiguration(
            evaluators,
            storage,
            chatClient,
            scenarioName: scenarioName);
    }

    /// <summary>
    /// Quality-mode evaluators: relevance, coherence, fluency, groundedness.
    /// </summary>
    public static IList<IEvaluator> QualityEvaluators() =>
    [
        new RelevanceEvaluator(),
        new CoherenceEvaluator(),
        new FluencyEvaluator(),
        new GroundednessEvaluator(),
    ];

    /// <summary>
    /// Configures OpenTelemetry tracing for telemetry mode.
    /// Exports spans to console and optionally to an OTLP endpoint.
    /// </summary>
    public static TracerProvider BuildTelemetryProvider()
    {
        var builder = Sdk.CreateTracerProviderBuilder()
            .SetResourceBuilder(ResourceBuilder.CreateDefault().AddService("MyApp.Evals"))
            .AddSource("Microsoft.Extensions.AI")
            .AddSource("MyApp")
            .AddConsoleExporter();

        var otlpEndpoint = Environment.GetEnvironmentVariable("OTEL_EXPORTER_OTLP_ENDPOINT");
        if (!string.IsNullOrEmpty(otlpEndpoint))
        {
            builder.AddOtlpExporter();
        }

        return builder.Build()!;
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Quality-mode evaluations: scores responses on relevance, coherence, fluency, groundedness.
/// </summary>
[TestClass]
public class QualityTests
{
    private static ReportingConfiguration? s_config;
    private static IChatClient? s_chatClient;

    [ClassInitialize]
    public static void Initialize(TestContext _)
    {
        s_chatClient = CreateChatClient();
        s_config = EvalConfiguration.CreateReportingConfiguration(
            EvalConfiguration.QualityEvaluators(),
            scenarioName: nameof(QualityTests),
            s_chatClient);
    }

    [ClassCleanup]
    public static async Task Cleanup()
    {
        if (s_config is not null)
        {
            await s_config.DisposeAsync();
        }

        (s_chatClient as IDisposable)?.Dispose();
    }

    [TestMethod]
    public async Task Coach_responds_relevantly_to_greeting()
    {
        await using var scenario = await s_config!.CreateScenarioRunAsync(
            scenarioName: nameof(Coach_responds_relevantly_to_greeting));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello, I need coaching advice on time management."),
        };

        var response = await s_chatClient!.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        scenario.AssertAllNumericMetricsAreAbove(3.0f);
    }

    [TestMethod]
    public async Task Coach_provides_coherent_action_plan()
    {
        await using var scenario = await s_config!.CreateScenarioRunAsync(
            scenarioName: nameof(Coach_provides_coherent_action_plan));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a productivity coach. Provide actionable advice."),
            new(ChatRole.User, "Give me a 3-step plan to improve my focus during work hours."),
        };

        var response = await s_chatClient!.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        scenario.AssertAllNumericMetricsAreAbove(3.0f);
    }

    private static IChatClient CreateChatClient()
    {
        // Uses AZURE_OPENAI_ENDPOINT and AZURE_OPENAI_API_KEY env vars,
        // or override via configuration for local dev.
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? "https://localhost";
        var key = Environment.GetEnvironmentVariable("AZURE_OPENAI_API_KEY") ?? "";

        return new Azure.AI.Inference.ChatCompletionsClient(
                new Uri(endpoint),
                new Azure.AzureKeyCredential(key))
            .AsChatClient("gpt-4o-mini");
    }
}

using Microsoft.Extensions.AI;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using OpenTelemetry.Trace;

namespace MyApp.Evals;

/// <summary>
/// Telemetry-mode tests: verifies spans are emitted for AI operations.
/// Run with OTEL_EXPORTER_OTLP_ENDPOINT set to collect distributed traces.
/// </summary>
[TestClass]
public class TelemetryTests
{
    private static TracerProvider? s_tracerProvider;

    [ClassInitialize]
    public static void Initialize(TestContext _)
    {
        s_tracerProvider = EvalConfiguration.BuildTelemetryProvider();
    }

    [ClassCleanup]
    public static void Cleanup()
    {
        s_tracerProvider?.Dispose();
    }

    [TestMethod]
    public async Task Chat_completion_emits_trace_spans()
    {
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? "https://localhost";
        var key = Environment.GetEnvironmentVariable("AZURE_OPENAI_API_KEY") ?? "";

        using var client = new Azure.AI.Inference.ChatCompletionsClient(
                new Uri(endpoint),
                new Azure.AzureKeyCredential(key))
            .AsChatClient("gpt-4o-mini");

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is 2+2?"),
        };

        var response = await client.GetResponseAsync(messages);

        // Force flush so spans are exported
        s_tracerProvider!.ForceFlush();

        Assert.IsNotNull(response);
        Assert.IsFalse(string.IsNullOrWhiteSpace(response.Message.Text));
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Compare-mode evaluations: runs the same scenarios across different model/prompt
/// configurations so results can be compared side-by-side in reports.
/// Tag each run with a label via the EVAL_RUN_LABEL env var (e.g., "baseline", "candidate").
/// </summary>
[TestClass]
public class CompareTests
{
    private static ReportingConfiguration? s_config;
    private static IChatClient? s_chatClient;
    private static string s_runLabel = "default";

    [ClassInitialize]
    public static void Initialize(TestContext _)
    {
        s_runLabel = Environment.GetEnvironmentVariable("EVAL_RUN_LABEL") ?? "default";
        s_chatClient = CreateChatClient();
        s_config = EvalConfiguration.CreateReportingConfiguration(
            EvalConfiguration.QualityEvaluators(),
            scenarioName: $"Compare_{s_runLabel}",
            s_chatClient);
    }

    [ClassCleanup]
    public static async Task Cleanup()
    {
        if (s_config is not null)
        {
            await s_config.DisposeAsync();
        }

        (s_chatClient as IDisposable)?.Dispose();
    }

    [TestMethod]
    public async Task Compare_coaching_response_quality()
    {
        await using var scenario = await s_config!.CreateScenarioRunAsync(
            scenarioName: $"coaching_quality_{s_runLabel}");

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a productivity coach."),
            new(ChatRole.User, "How do I stay motivated when working remotely?"),
        };

        var response = await s_chatClient!.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        // In compare mode we record without hard-failing; review reports to compare.
        scenario.AssertAllNumericMetricsAreAbove(2.0f);
    }

    [TestMethod]
    public async Task Compare_structured_advice_quality()
    {
        await using var scenario = await s_config!.CreateScenarioRunAsync(
            scenarioName: $"structured_advice_{s_runLabel}");

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a productivity coach. Respond with numbered steps."),
            new(ChatRole.User, "How should I prioritize tasks when everything feels urgent?"),
        };

        var response = await s_chatClient!.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        scenario.AssertAllNumericMetricsAreAbove(2.0f);
    }

    private static IChatClient CreateChatClient()
    {
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? "https://localhost";
        var key = Environment.GetEnvironmentVariable("AZURE_OPENAI_API_KEY") ?? "";
        var model = Environment.GetEnvironmentVariable("EVAL_MODEL") ?? "gpt-4o-mini";

        return new Azure.AI.Inference.ChatCompletionsClient(
                new Uri(endpoint),
                new Azure.AzureKeyCredential(key))
            .AsChatClient(model);
    }
}

