using Microsoft.Extensions.AI;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using OpenTelemetry.Trace;

namespace MyApp.Evals;

/// <summary>
/// Telemetry-mode tests: verifies spans are emitted for AI operations.
/// Run with OTEL_EXPORTER_OTLP_ENDPOINT set to collect distributed traces.
/// </summary>
[TestClass]
public class TelemetryTests
{
    private static TracerProvider? s_tracerProvider;

    [ClassInitialize]
    public static void Initialize(TestContext _)
    {
        s_tracerProvider = EvalConfiguration.BuildTelemetryProvider();
    }

    [ClassCleanup]
    public static void Cleanup()
    {
        s_tracerProvider?.Dispose();
    }

    [TestMethod]
    public async Task Chat_completion_emits_trace_spans()
    {
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? "https://localhost";
        var key = Environment.GetEnvironmentVariable("AZURE_OPENAI_API_KEY") ?? "";

        using var client = new Azure.AI.Inference.ChatCompletionsClient(
                new Uri(endpoint),
                new Azure.AzureKeyCredential(key))
            .AsChatClient("gpt-4o-mini");

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is 2+2?"),
        };

        var response = await client.GetResponseAsync(messages);

        // Force flush so spans are exported
        s_tracerProvider!.ForceFlush();

        Assert.IsNotNull(response);
        Assert.IsFalse(string.IsNullOrWhiteSpace(response.Message.Text));
    }
}

