using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Compare-mode evaluations: runs the same scenarios across different model/prompt
/// configurations so results can be compared side-by-side in reports.
/// Tag each run with a label via the EVAL_RUN_LABEL env var (e.g., "baseline", "candidate").
/// </summary>
[TestClass]
public class CompareTests
{
    private static ReportingConfiguration? s_config;
    private static IChatClient? s_chatClient;
    private static string s_runLabel = "default";

    [ClassInitialize]
    public static void Initialize(TestContext _)
    {
        s_runLabel = Environment.GetEnvironmentVariable("EVAL_RUN_LABEL") ?? "default";
        s_chatClient = CreateChatClient();
        s_config = EvalConfiguration.CreateReportingConfiguration(
            EvalConfiguration.QualityEvaluators(),
            scenarioName: $"Compare_{s_runLabel}",
            s_chatClient);
    }

    [ClassCleanup]
    public static async Task Cleanup()
    {
        if (s_config is not null)
        {
            await s_config.DisposeAsync();
        }

        (s_chatClient as IDisposable)?.Dispose();
    }

    [TestMethod]
    public async Task Compare_coaching_response_quality()
    {
        await using var scenario = await s_config!.CreateScenarioRunAsync(
            scenarioName: $"coaching_quality_{s_runLabel}");

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a productivity coach."),
            new(ChatRole.User, "How do I stay motivated when working remotely?"),
        };

        var response = await s_chatClient!.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        // In compare mode we record without hard-failing; review reports to compare.
        scenario.AssertAllNumericMetricsAreAbove(2.0f);
    }

    [TestMethod]
    public async Task Compare_structured_advice_quality()
    {
        await using var scenario = await s_config!.CreateScenarioRunAsync(
            scenarioName: $"structured_advice_{s_runLabel}");

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a productivity coach. Respond with numbered steps."),
            new(ChatRole.User, "How should I prioritize tasks when everything feels urgent?"),
        };

        var response = await s_chatClient!.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        scenario.AssertAllNumericMetricsAreAbove(2.0f);
    }

    private static IChatClient CreateChatClient()
    {
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? "https://localhost";
        var key = Environment.GetEnvironmentVariable("AZURE_OPENAI_API_KEY") ?? "";
        var model = Environment.GetEnvironmentVariable("EVAL_MODEL") ?? "gpt-4o-mini";

        return new Azure.AI.Inference.ChatCompletionsClient(
                new Uri(endpoint),
                new Azure.AzureKeyCredential(key))
            .AsChatClient(model);
    }
}

